#!/usr/bin/env Rscript
# Rarefaction Curve Plot
# Taxonomic saturation (rarefaction) curves across five taxonomic ranks.
# Extracted from Figure1_composite_v2.R (Panel e).
#
# Input data generated by: oral_sampling_saturation_curve_analysis.py
# Output: rarefaction_curve.pdf / rarefaction_curve.png

library(tidyverse)
library(mgcv)
library(scales)

# ---------------------------------------------------------------------------
# Global theme & font sizing
#   base_sz raised to 22 so text is large and legible on a compact canvas.
# ---------------------------------------------------------------------------
base_sz <- 22
text_sz <- base_sz / .pt

update_geom_defaults("text", list(family = "sans"))
update_geom_defaults("label", list(family = "sans"))

theme_set(theme_minimal(base_size = base_sz, base_family = "sans"))

# ---------------------------------------------------------------------------
# Load rarefaction data
# ---------------------------------------------------------------------------
rarefaction_file <- paste0(
  "/home/yanglun/YSD/global_oral/global_oral_v2/oral-v2-02/",
  "01-overview-sampling-distribution/02-patch-pipeline-map/",
  "output/rarefaction_pcofg.tsv"
)

df_rare <- read.table(rarefaction_file, header = TRUE, sep = "\t") %>%
  pivot_longer(
    cols      = c("Phylum", "Class", "Order", "Family", "Genus"),
    names_to  = "Taxonomy",
    values_to = "Unique_taxa"
  ) %>%
  mutate(Taxonomy = factor(Taxonomy,
                           levels = c("Genus", "Family", "Order",
                                      "Class", "Phylum")))

# ---------------------------------------------------------------------------
# Saturation curves with GAM smoothing
# ---------------------------------------------------------------------------
p_e <- ggplot(df_rare, aes(x = Samples, y = Unique_taxa, color = Taxonomy)) +
  geom_smooth(
    method    = "gam",
    formula   = y ~ s(x, bs = "cs"),
    se        = FALSE,
    linewidth = 0.7
  ) +
  scale_color_manual(
    values = c(
      "Genus"  = "#5C6BC0",
      "Family" = "#FFB300",
      "Order"  = "#EF5350",
      "Class"  = "#26C6DA",
      "Phylum" = "#66BB6A"
    )
  ) +
  scale_x_continuous(
    breaks = seq(0, 80000, by = 20000),
    limits = c(0, 98000),
    labels = c("0", "20K", "40K", "60K", "80K"),
    expand = c(0, 0)
  ) +
  scale_y_continuous(
    breaks = c(0, 1000, 2000, 3000, 4000, 5000),
    labels = c("0", "1K", "2K", "3K", "4K", "5K"),
    expand = expansion(mult = c(0.1, 0.06))
  ) +
  # Inline rank labels — larger, positioned at x=81000
  annotate("text",
           x = 81000, y = 4900, label = "Genus",
           color = "#5C6BC0", fontface = "bold",
           size = base_sz / 3.8, hjust = 0) +
  annotate("text",
           x = 81000, y = 1400, label = "Family",
           color = "#FFB300", fontface = "bold",
           size = base_sz / 3.8, hjust = 0) +
  annotate("text",
           x = 81000, y = 800, label = "Order",
           color = "#EF5350", fontface = "bold",
           size = base_sz / 3.8, hjust = 0) +
  annotate("text",
           x = 81000, y = 350, label = "Class",
           color = "#26C6DA", fontface = "bold",
           size = base_sz / 3.8, hjust = 0) +
  annotate("text",
           x = 81000, y = 5, label = "Phylum",
           color = "#66BB6A", fontface = "bold",
           size = base_sz / 3.8, hjust = 0) +
  labs(x = "Samples", y = "Observed taxa") +
  coord_cartesian(clip = "off") +
  theme_classic(base_size = base_sz - 4, base_family = "sans") +
  theme(
    axis.text.x     = element_text(
      size = base_sz * 0.72,
      face = "bold", color = "#303030"
    ),
    axis.text.y     = element_text(
      size = base_sz * 0.72,
      face = "bold", color = "#303030"
    ),
    axis.title.y    = element_text(
      size = base_sz * 0.85,
      face = "bold", color = "#303030",
      margin = margin(r = 6)
    ),
    axis.title.x    = element_text(
      size = base_sz * 0.85,
      face = "bold", color = "#303030",
      margin = margin(t = 10)
    ),
    legend.position = "none",
    plot.margin     = margin(5, 5, 5, 5, unit = "pt"),
    plot.background = element_blank(),
    panel.background = element_blank()
  )

# ---------------------------------------------------------------------------
# Save output — compact canvas, large text
# ---------------------------------------------------------------------------
output_dir <- "/home/yanglun/YSD/global_oral/global_oral_v2/oral-v2-02/01-overview-sampling-distribution/02-patch-pipeline-map/output"
if (!dir.exists(output_dir)) dir.create(output_dir, recursive = TRUE)

ggsave(file.path(output_dir, "rarefaction_curve.pdf"),
       plot = p_e, width = 7, height = 5.5, device = "pdf")
ggsave(file.path(output_dir, "rarefaction_curve.png"),
       plot = p_e, width = 7, height = 5.5,
       device = "png", dpi = 600, bg = "white")

message("Rarefaction curve saved to: ",
        file.path(output_dir, "rarefaction_curve.pdf"))